package io.github.diodeme.ji.ai;

import java.net.URI;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.CompletionStage;

/** Resolves a durable credential reference into request-scoped secret material. */
@FunctionalInterface
public interface CredentialResolver {
    CompletionStage<CredentialMaterial> resolve(Request request);

    static CredentialResolver none() {
        return request -> CompletableFuture.completedFuture(CredentialMaterial.none());
    }

    record Request(String profileId, ProviderProtocolFamily family, URI origin,
                   CredentialReference reference, CancellationToken cancellation) {
        public Request {
            if (profileId == null || profileId.isBlank()) throw new IllegalArgumentException("profileId must not be blank");
            if (family == null) throw new IllegalArgumentException("family must not be null");
            if (origin == null || !origin.isAbsolute()) throw new IllegalArgumentException("origin must be absolute");
            if (reference == null) throw new IllegalArgumentException("reference must not be null");
            if (cancellation == null) throw new IllegalArgumentException("cancellation must not be null");
        }
    }
}
